window.LD=window.LD||{};window.LD["party/p4"]={"id":"p4","name":"The Mercy of Thornwall","poss":"The Mercy of Thornwall's","members":["h17","h11","h1","h14"],"leader":"h17","morale":99,"disposition":"predatory","motto":"Finders keepers. We find everything.","banner":{"c1":"#3c64c8","c2":"#2b2b33","emblem":"lantern"},"loc":"emberdeep","loc_name":"Emberdeep","goal":{"text":"to earn 5,600 silver between them before the season ends","kind":"purse","done":88,"progress":"6,868 silver, past the 5,600 aimed for","missed":false,"crew":"The Mercy of Thornwall","party":"p4"},"vows":[{"text":"to repay Amber Banner","day":6,"state":"kept","ended":16,"through":false,"progress":"kept on day 16 of season 1","crew":"The Mercy of Thornwall","party":"p4"},{"text":"to keep the peace: never draw first on another hero","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Mercy of Thornwall","party":"p4"},{"text":"to die rich","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Mercy of Thornwall","party":"p4"}],"doing":"last seen delving into Emberdeep","progress":null,"today":["Fought 1 fight: won 1; 4 foes down.","XP: Fenwick +918 (level 20!), Quill +912, Brix +958 (level 20!), Ottoline +954 (level 25!).","Coin between them: +17 silver.","Came away with 8 living coals, 5 ember cores, 4 salamander tails, a drake scale, a lump of ore.","Ate 8 rations."],"fights_today":["f279"],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"salt_on_the_wind","title":"Salt on the Wind","tone":"sad","meter":"6/8","bpm":69,"diff":3,"day":29,"night":"n49","n":6,"by":null,"lead":{"id":"h17","name":"Fenwick","skill":0.811,"inst":"flute"}},"renown":769,"season":{"wins":9,"bosses":2,"floors":8,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":2},"career":{"wins":30,"bosses":5,"floors":24,"gold":0,"deaths":0,"fled":3,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":4},"former":[],"fallen":[],"travel":null,"wagon":null,"pace_gap":3,"rels":[{"party":"p2","score":100},{"party":"p3","score":100},{"party":"p1","score":100},{"party":"p6","score":17},{"party":"p5","score":16}],"events":[{"id":"e29","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Fenwick and Quill shake on it at The Sagging Beam: they are now The Mercy of Thornwall. (Predatory, by the look of them.)","heroes":["h17","h11"],"parties":["p4"],"loc":"thornwall","wx":"heat"},{"id":"e229","day":6,"season":1,"sday":6,"kind":"rescue","imp":4,"text":"RESCUE in Goblin Camp: Isolde (Sage's hero) finds Fenwick (Quinn's hero) bleeding in the dark and does not walk past. 1 potion later, Fenwick is breathing properly.","heroes":["h18","h17","h4","h2","h11"],"parties":["p2","p4"],"loc":"goblin_camp","rescuers":["h18","h4","h2"]},{"id":"e490","day":13,"season":1,"sday":13,"kind":"rescue","imp":4,"text":"Brix (Griffin's hero) owes Duren (Sam's hero) a life now: The Azure Gravediggers pulled The Mercy of Thornwall out of trouble in Cragtooth Warren, 2 potions poorer.","heroes":["h3","h1","h15","h5","h9","h17","h11"],"parties":["p3","p4"],"loc":"cragtooth_warren","rescuers":["h3","h15","h5","h9"]},{"id":"e602","day":16,"season":1,"sday":16,"kind":"vow_kept","imp":5,"text":"VOW KEPT. Debt paid: The Mercy of Thornwall pulls Amber Banner out of trouble, as sworn on day 6 of season 1.","heroes":["h17","h11","h1"],"parties":["p4"],"cause":"e230"},{"id":"e620","day":17,"season":1,"sday":17,"kind":"curse","imp":5,"text":"Sister Amberline takes the Whispering Crown from Brix's shaking hands, says some very old words over it, and breaks it. 10 silver, and worth every coin.","heroes":["h1"],"parties":["p4"],"loc":"thornwall"},{"id":"e745","day":20,"season":1,"sday":20,"kind":"road","imp":3,"text":"At the Shrine of Quiet Names Quill hears a whisper from the crypts say their own name, kindly, and then nothing. Quill pays 1 copper to the dish and walks on shaken and strangely at peace.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ashfen~ashveil_crypts","road_rec":"r148"},{"id":"e746","day":20,"season":1,"sday":20,"kind":"night","imp":2,"text":"Quill's ghost story in the Ashveil Crypts goes on too long and never really ends. Brix lies awake waiting for the ending.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e756","day":20,"season":1,"sday":20,"kind":"meet","imp":2,"text":"The Newts of Ashfen and The Mercy of Thornwall share a fire in the Ashveil Crypts. Bramble shares directions.","heroes":["h13","h7","h17","h11","h1"],"parties":["p1","p4"],"loc":"ashveil_crypts"},{"id":"e757","day":20,"season":1,"sday":20,"kind":"journey","imp":2,"text":"The Newts of Ashfen and The Mercy of Thornwall fall in together on the road to the Ashveil Crypts and spend the miles arguing about a shortcut that turned out to be a longcut.","heroes":["h13","h7","h17","h11","h1"],"parties":["p1","p4"]},{"id":"e765","day":20,"season":1,"sday":20,"kind":"campfire","imp":1,"text":"Brix and Fenwick walk point together all afternoon and say about nine words. Good words.","heroes":["h1","h17"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e777","day":21,"season":1,"sday":21,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into the Ashveil Crypts, partly explored (64%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e778","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"On floor 1 of the Ashveil Crypts, the Mercy of Thornwall handles 2 Skeletons and 2 Giant Rats. The last giant rat decides enough is enough, and goes. Quill's Force Bolt put the skeleton down. Brix did the unglamorous work that kept the line from breaking. Loot: 6 bones. Fenwick hates the dead more than anything, and fights through it anyway.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f83","foes":["skeleton","skeleton","giant_rat"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-30,"wx":"rain"},{"id":"e779","day":21,"season":1,"sday":21,"kind":"treasure","imp":2,"text":"Brix kicks over a rotten crate on floor 1 of the Ashveil Crypts. Out rolls 29 silver.","heroes":["h1","h17","h11"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e798","day":21,"season":1,"sday":21,"kind":"tarot","imp":1,"text":"On the last night before the Ashveil Crypts, Brix spreads a cloak by the fire and reads the Pressed-Leaf Tarot for the whole of The Mercy of Thornwall: the Three of Wands upside down, the Ace of Swords upside down and the Ten of Swords. Brix goes quiet over the cards.","heroes":["h17","h1"],"parties":["p4"],"loc":"ashveil_crypts","reading":"r160","wx":"rain"},{"id":"e803","day":21,"season":1,"sday":21,"kind":"campfire","imp":1,"text":"Fenwick and Brix have been in The Mercy of Thornwall together for a fortnight. They've stopped saying \"please\" and started saying \"pass it\".","heroes":["h17","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e804","day":21,"season":1,"sday":21,"kind":"campfire","imp":1,"text":"Fourteen days in The Mercy of Thornwall: Quill and Brix have learned which of them snores and which of them lies about snoring.","heroes":["h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e819","day":22,"season":1,"sday":22,"kind":"fight","imp":1,"text":"Back on floor 1 of the Ashveil Crypts, the Mercy of Thornwall dispatches 2 Skeletons and a Giant Rat. Fenwick ended it with Reckless Swing. Loot: 7 bones, 2 crypt-caps.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f85","foes":["skeleton","giant_rat","skeleton"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"again","reworded":-6,"wx":"rain"},{"id":"e837","day":22,"season":1,"sday":22,"kind":"meet","imp":2,"text":"The Mercy of Thornwall and Amber Banner share a fire in the Ashveil Crypts. There is a short argument about the best road to Ironhaven.","heroes":["h17","h11","h1","h18","h4","h2"],"parties":["p4","p2"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e842","day":22,"season":1,"sday":22,"kind":"campfire","imp":1,"text":"Fenwick tells Brix something they've never told anyone. Brix keeps it.","heroes":["h1","h17"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e855","day":23,"season":1,"sday":23,"kind":"fight","imp":1,"text":"The Mercy of Thornwall gets the better of a Skeleton Archer and a Skeleton on floor 2 of the Ashveil Crypts. The final blow was Brix's Magic Missile. Loot: 7 bones.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f88","foes":["skeleton_archer","skeleton"],"where":"on floor 2 of The Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-11,"wx":"rain"},{"id":"e856","day":23,"season":1,"sday":23,"kind":"night","imp":2,"text":"Something small and clever gets into The Mercy of Thornwall's camp in the Ashveil Crypts overnight. Fenwick wakes up 10 silver and 1 ration lighter.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e876","day":23,"season":1,"sday":23,"kind":"campfire","imp":1,"text":"Brix builds Fenwick a small brass gadget that mostly works. Fenwick keeps it anyway.","heroes":["h1","h17"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e879","day":24,"season":1,"sday":24,"kind":"treasure","imp":1,"text":"Fenwick insists on checking one more passage on floor 3 of the Ashveil Crypts, and it opens onto a narrow crawlway that opens into a dry cavern: 2 gold pieces, 23 silver and a gem.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e915","day":25,"season":1,"sday":25,"kind":"fight","imp":1,"text":"Win number four in a row: the Mercy of Thornwall dispatches a Wraith on floor 3 of the Ashveil Crypts. Quill's Raise Skeleton put an extra body on the right side of the fight.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f99","foes":["wraith"],"where":"on floor 3 of The Ashveil Crypts","won":true,"close":false,"shape":"streak","reworded":-26,"wx":"rain"},{"id":"e919","day":25,"season":1,"sday":25,"kind":"meet","imp":1,"text":"The Mercy of Thornwall runs into The Azure Gravediggers in the Ashveil Crypts. Stories are exchanged, most of them exaggerated.","heroes":["h17","h11","h1","h3","h15","h5","h9"],"parties":["p4","p3"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e947","day":26,"season":1,"sday":26,"kind":"sniped","imp":3,"text":"Word reaches The Mercy of Thornwall on floor 3 of the Ashveil Crypts: The Newts of Ashfen killed Vessimir the Unburied today. Nobody says much. The side passages still need mapping.","heroes":["h17","h11","h1","h13","h7"],"parties":["p4","p1"],"loc":"ashveil_crypts","snipers":["h13","h7"],"where":"inside","boss":"Vessimir the Unburied","in_fight":"f102","wx":"rain"},{"id":"e949","day":26,"season":1,"sday":26,"kind":"treasure","imp":3,"text":"Behind a mural hall nobody has seen in a century on floor 4 of the Ashveil Crypts, nobody had been in years. Brix comes out with 2 gold pieces, 20 silver and a gem.","heroes":["h1","h17","h11"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e956","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"A guardian statue's gaze slides off Brix as if off a wall. Brix walks by with a pleasant nod.","heroes":["h1"],"parties":["p4"],"loc":"ashveil_crypts","skill":"poker_face","wx":"rain"},{"id":"e977","day":27,"season":1,"sday":27,"kind":"delve_done","imp":3,"text":"The Mercy of Thornwall comes up after 7 days in the Ashveil Crypts. They got all the way to the bottom, mapped 64% of it, found a narrow crawlway that opens into a dry cavern and a mural hall nobody has seen in a century, disarmed 2 traps and came away with 98 silver between them. The Newts of Ashfen got the boss. The Mercy of Thornwall got the rest. Counting everyone's digging, the Ashveil Crypts is picked clean (99%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","days":7,"bottom":true,"rooms":["a narrow crawlway that opens into a dry cavern","a mural hall nobody has seen in a century"],"gold":98,"wx":"rain"},{"id":"e978","day":27,"season":1,"sday":27,"kind":"talent","imp":2,"text":"Quill tries to read Brix's face over a hand of cards for an hour, gives up, and asks to see the cards instead.","heroes":["h1","h11"],"parties":["p4"],"loc":"ashveil_crypts","skill":"poker_face","wx":"rain"},{"id":"e988","day":27,"season":1,"sday":27,"kind":"meet","imp":1,"text":"Amber Banner warns The Mercy of Thornwall about what's lurking in the Ashveil Crypts. The Mercy of Thornwall pretends to already know.","heroes":["h18","h4","h2","h17","h11","h1"],"parties":["p2","p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e1010","day":28,"season":1,"sday":28,"kind":"road","imp":3,"text":"A rainbow stands so low over the road to Ashfen that Quill could touch its foot. Quill reaches out, and the colour runs warm across her hand.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ashfen~ashveil_crypts","road_rec":"r183"},{"id":"e1038","day":28,"season":1,"sday":28,"kind":"journey","imp":2,"text":"The Mercy of Thornwall and The Newts of Ashfen walk to Ashfen together. Someone brings up what they'd do if they retired. Someone always does.","heroes":["h17","h11","h1","h13","h7"],"parties":["p4","p1"]},{"id":"e1045","day":28,"season":1,"sday":28,"kind":"campfire","imp":2,"text":"Duke the dog has chosen Quill. Quill pretends to mind. Fenwick is quietly delighted.","heroes":["h17","h11"],"parties":["p4"],"loc":"ashfen","wx":"rain"},{"id":"e1062","day":29,"season":1,"sday":29,"kind":"road","imp":3,"text":"Osk jumps out of a hedge and holds up a ledger like a shield before Quill can so much as blink. Nobody is hurt. A note is made.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ashfen~bleakmarsh","traveller":"osk","road_rec":"r196"},{"id":"e1070","day":29,"season":1,"sday":29,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Newts of Ashfen, The Azure Gravediggers and The Mercy of Thornwall are all after Mother Thornmere. Thornmere Ruins has one way down and room for one winner.","heroes":["h13","h7","h3","h15","h5","h9","h17","h11","h1"],"parties":["p1","p3","p4"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1073","day":29,"season":1,"sday":29,"kind":"meet","imp":2,"text":"The Newts of Ashfen warn The Mercy of Thornwall about what's lurking in Bleakmarsh. The Mercy of Thornwall pretends to already know.","heroes":["h13","h7","h17","h11","h1"],"parties":["p1","p4"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1074","day":29,"season":1,"sday":29,"kind":"talent","imp":1,"text":"Fenwick jogs the last mile into camp because walking felt too slow.","heroes":["h17"],"parties":["p4"],"loc":"bleakmarsh","skill":"cant_stop_now","wx":"rain"},{"id":"e1076","day":29,"season":1,"sday":29,"kind":"music","imp":3,"text":"The Mercy of Thornwall sang \"Salt on the Wind\" under a clear sky last night, and somewhere in the chorus it became their anthem. Ask any of them; they'll sing it for you.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"bleakmarsh","anthem":"salt_on_the_wind","night":"n49","wx":"rain"},{"id":"e1091","day":30,"season":1,"sday":30,"kind":"night","imp":2,"text":"Fenwick tells a ghost story by the fire in Thornmere Ruins. Brix insists on keeping the fire going until dawn. For warmth.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1120","day":30,"season":1,"sday":30,"kind":"goal_missed","imp":3,"text":"Not this time: The Mercy of Thornwall's goal (earn 550 silver between them before the season ends) falls short (339 of 550 silver).","heroes":["h17","h11","h1"],"parties":["p4"]},{"id":"e1151","day":31,"season":2,"sday":1,"kind":"talent","imp":2,"text":"Brix times Fenwick chopping firewood. Neither believes the result.","heroes":["h17","h1"],"parties":["p4"],"loc":"goblin_camp","skill":"cant_stop_now"},{"id":"e1165","day":31,"season":2,"sday":1,"kind":"argument","imp":2,"text":"It starts with whose idea the last dungeon was. It ends with Fenwick and Brix sleeping on opposite sides of the fire.","heroes":["h17","h1"],"parties":["p4"]},{"id":"e1166","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Thirty days in The Mercy of Thornwall. Fenwick and Quill have stopped keeping score of who owes whom.","heroes":["h17","h11"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e1170","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Mercy of Thornwall: to keep the peace: never draw first on another hero. Easy to say on day one.","heroes":["h17","h11","h1"],"parties":["p4"]},{"id":"e1181","day":32,"season":2,"sday":2,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into Goblin Camp, partly explored (39%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e1182","day":32,"season":2,"sday":2,"kind":"fight","imp":2,"text":"On floor 1 of Goblin Camp, the Mercy of Thornwall sees off 2 Goblins and 2 Giant Rats. Fenwick stepped in with Reckless Swing, and the goblin was on the ground. Loot: 1 silver each, 3 goblin ears, 2 rat haunches.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"goblin_camp","fight":"f110","foes":["goblin","giant_rat","giant_rat"],"where":"on floor 1 of Goblin Camp","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e1194","day":32,"season":2,"sday":2,"kind":"gift","imp":2,"text":"Brix gives Quill a Medal of Baked Crust. \"For luck,\" Brix says, and won't explain further.","heroes":["h1","h11"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e1218","day":33,"season":2,"sday":3,"kind":"fight","imp":2,"text":"Quill keeps everyone up as the Mercy of Thornwall handles 3 Goblins and a Goblin Shaman on floor 2 of Goblin Camp. Quill's Raise Skeleton put an extra body on the right side of the fight. Brix kept a cool head while everyone else was shouting. Loot: 5 silver each, 5 goblin ears.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"goblin_camp","fight":"f117","foes":["goblin","goblin","goblin_shaman"],"where":"on floor 2 of Goblin Camp","won":true,"close":false,"shape":"hero","reworded":-27},{"id":"e1223","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Quill recognises a carving of the dungeon's keeper and quietly turns to the right chapter. Chalk it up to Prepared for This.","heroes":["h11"],"parties":["p4"],"loc":"goblin_camp","skill":"prepared_for_this"},{"id":"e1250","day":34,"season":2,"sday":4,"kind":"boss","imp":5,"text":"The Mercy of Thornwall kills Gruk the Warchief's Heir, a Goblin Shaman and a Goblin Archer at the bottom of Goblin Camp and lives to tell of it. Gruk the Warchief's Heir stood smiling at Brix for a whole round. Poker Face. Fenwick's Reckless Swing was where the fight changed hands. Quill kept them off everyone with Prepared for This. Fenwick's Bloodlust kicked in when it counted. Loot: 26 silver each, 6 goblin ears, 3 trinkets.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"goblin_camp","fight":"f121","foes":["goblin_warchief","goblin_shaman","goblin_archer"],"where":"at the bottom of Goblin Camp","won":true,"close":false,"shape":"plain","reworded":-24},{"id":"e1251","day":34,"season":2,"sday":4,"kind":"treasure","imp":2,"text":"Under Gruk the Warchief's Heir's nest in Goblin Camp: 6 gold pieces and 8 silver nobody else will ever claim.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"goblin_camp","in_fight":"f121"},{"id":"e1269","day":34,"season":2,"sday":4,"kind":"big_move","imp":4,"text":"The Mercy of Thornwall kills Gruk the Warchief's Heir, a Goblin Shaman and a Goblin Archer at the bottom of Goblin Camp and lives to tell of it. On the table: Fenwick +64 renown (5th to 1st), Brix +60 (4th to 2nd) and Quill +56 (8th to 3rd). The Mercy of Thornwall +115 party renown (3rd to 1st among the crews).","heroes":["h17","h1","h11"],"parties":["p4"],"cause":"e1250","moves":[{"hero":"h17","gain":64,"from":5,"to":1},{"hero":"h1","gain":60,"from":4,"to":2},{"hero":"h11","gain":56,"from":8,"to":3}],"party_moves":[{"party":"p4","gain":115,"from":3,"to":1}],"fight":"f121"},{"id":"e1281","day":35,"season":2,"sday":5,"kind":"delve_done","imp":1,"text":"The Mercy of Thornwall comes up after 4 days in Goblin Camp. They got all the way to the bottom, mapped 57% of it and came away with 164 silver between them. Counting everyone's digging, Goblin Camp is mostly explored (72%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"goblin_camp","days":4,"bottom":true,"rooms":[],"gold":164,"wx":"fog"},{"id":"e1282","day":35,"season":2,"sday":5,"kind":"talent","imp":1,"text":"Quill reads up on what lives on the next floor down and underlines the weak points in red. (Prepared for This, if anyone's asking.)","heroes":["h11"],"parties":["p4"],"loc":"goblin_camp","skill":"prepared_for_this","wx":"fog"},{"id":"e1335","day":36,"season":2,"sday":6,"kind":"campfire","imp":1,"text":"Fenwick and Quill share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h17","h11"],"parties":["p4"],"loc":"thornwall","wx":"heat"},{"id":"e1344","day":37,"season":2,"sday":7,"kind":"map_bought","imp":2,"text":"The Mercy of Thornwall buys a map of the Wolf Den in Thornwall for 14 silver, drawn by Ash. The place is partly explored (36%).","heroes":["h17","h11","h1","h12"],"parties":["p4"],"loc":"thornwall","wx":"heat"},{"id":"e1359","day":37,"season":2,"sday":7,"kind":"campfire","imp":1,"text":"Fenwick and Brix have shared a month of roads in The Mercy of Thornwall. Ask either one about the other and settle in for a story.","heroes":["h17","h1"],"parties":["p4"],"loc":"greenwood"},{"id":"e1361","day":37,"season":2,"sday":7,"kind":"campfire","imp":1,"text":"Thirty days in The Mercy of Thornwall. Quill and Brix have stopped keeping score of who owes whom.","heroes":["h11","h1"],"parties":["p4"],"loc":"greenwood"},{"id":"e1362","day":37,"season":2,"sday":7,"kind":"campfire","imp":1,"text":"Brix and Fenwick have a two-hour argument about whether a goblin could beat a goose. It is never resolved.","heroes":["h1","h17"],"parties":["p4"],"loc":"greenwood"},{"id":"e1365","day":37,"season":2,"sday":7,"kind":"ledger","imp":2,"text":"THE LEDGER: 21 hauls sold this week, 1,312 silver in all. Biggest haul: Tobias, 227 silver in Ironhaven. Back up from the deep: The Mercy of Thornwall (4 days in Goblin Camp).","heroes":["h6","h17"],"parties":["p4"]},{"id":"e1372","day":38,"season":2,"sday":8,"kind":"skim","imp":2,"text":"Fenwick quietly pockets an extra 39 silver while The Mercy of Thornwall counts the rest. Nobody notices.","heroes":["h17"],"parties":["p4"],"loc":"greenwood","in_fight":"f130"},{"id":"e1373","day":38,"season":2,"sday":8,"kind":"ambush","imp":2,"text":"It's 2 Bounty Hunters and the Bounty Hunters' Captain against the Mercy of Thornwall in the Greenwood, sent for the price on Fenwick's head, and it isn't close. Force Bolt, from Quill, was the last thing the bounty hunter saw. The others will say it was close. Brix made sure it wasn't. Fenwick kept the bleeding to a minimum. Loot: 14 silver each, 7 stolen goods, 1 gem.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"greenwood","fight":"f130","foes":["bandit_captain","bandit","bandit"],"where":"in The Greenwood, sent for the price on Fenwick's head","won":true,"close":false,"shape":"foe","reworded":-13},{"id":"e1374","day":38,"season":2,"sday":8,"kind":"road","imp":3,"text":"Granfer Oake predicts snow for the following Tuesday to Fenwick. Nobody asked, and it is Friday.","heroes":["h17","h1","h11"],"parties":["p4"],"road":"greenwood~wolf_den","traveller":"oake","road_rec":"r253"},{"id":"e1388","day":38,"season":2,"sday":8,"kind":"tarot","imp":2,"text":"The Mercy of Thornwall sit in a ring while Brix turns the Pressed-Leaf Tarot for all of them before the Wolf Den: the Eight of Wands, the Seven of Swords and the Ace of Pentacles. Brix says it could go either way.","heroes":["h17","h1"],"parties":["p4"],"loc":"wolf_den","reading":"r257"},{"id":"e1400","day":39,"season":2,"sday":9,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into the Wolf Den, partly explored (36%), map in hand.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den"},{"id":"e1401","day":39,"season":2,"sday":9,"kind":"treasure","imp":2,"text":"Mapping floor 1 of the Wolf Den, Fenwick finds a bone-strewn nest. Inside: 10 silver and a gem.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den"},{"id":"e1425","day":39,"season":2,"sday":9,"kind":"campfire","imp":1,"text":"Brix talks Quill through a bad night about being forgotten. Neither mentions it in the morning. Both remember.","heroes":["h1","h11"],"parties":["p4"],"loc":"wolf_den"},{"id":"e1454","day":40,"season":2,"sday":10,"kind":"fight","imp":1,"text":"The Mercy of Thornwall, in fine spirits lately, beats 2 Wolves and a Dire Wolf on floor 2 of the Wolf Den. The fight turned on Quill's Arcane Torrent. Loot: 2 wolf haunches, 1 pelt.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den","fight":"f137","foes":["dire_wolf","wolf","wolf"],"where":"on floor 2 of The Wolf Den","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1455","day":40,"season":2,"sday":10,"kind":"treasure","imp":1,"text":"Quill kicks over a rotten crate on floor 2 of the Wolf Den. Out rolls 1 gold piece, 14 silver and a gem.","heroes":["h11","h17","h1"],"parties":["p4"],"loc":"wolf_den"},{"id":"e1456","day":40,"season":2,"sday":10,"kind":"night","imp":1,"text":"Quill follows strange lights away from the camp in the Wolf Den, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den"},{"id":"e1474","day":41,"season":2,"sday":11,"kind":"boss","imp":5,"text":"The long way down ends at the bottom of the Wolf Den, where the Mercy of Thornwall finishes off Old Grizzlemaw's Widow, a Dire Wolf and a Wolf. The final blow was Brix's Magic Missile. Shield Wall from Fenwick kept the back row out of it. Brix was wherever the trouble was, every time. Quill kept them off everyone with Prepared for This. Loot: 6 pelts, 9 fangs & claws, Grizzlemaw's honeycomb.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den","fight":"f141","foes":["cave_bear","dire_wolf","wolf"],"where":"at the bottom of The Wolf Den","won":true,"close":false,"shape":"place","reworded":-37},{"id":"e1475","day":41,"season":2,"sday":11,"kind":"treasure","imp":1,"text":"Under Old Grizzlemaw's Widow's nest in the Wolf Den: 8 gold pieces nobody else will ever claim.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den","in_fight":"f141"},{"id":"e1490","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Mercy of Thornwall's plan for the season, as told to the barkeep: to find a relic of the old world.","heroes":["h17","h11","h1"],"parties":["p4"]},{"id":"e1498","day":41,"season":2,"sday":11,"kind":"big_move","imp":4,"text":"The long way down ends at the bottom of the Wolf Den, where the Mercy of Thornwall finishes off Old Grizzlemaw's Widow, a Dire Wolf and a Wolf. On the table: Quill +67 renown (6th to 2nd), Brix +65 (7th to 3rd) and Fenwick +63 (5th to 1st). The Mercy of Thornwall +122 party renown (2nd to 1st among the crews).","heroes":["h11","h1","h17"],"parties":["p4"],"cause":"e1474","moves":[{"hero":"h11","gain":67,"from":6,"to":2},{"hero":"h1","gain":65,"from":7,"to":3},{"hero":"h17","gain":63,"from":5,"to":1}],"party_moves":[{"party":"p4","gain":122,"from":2,"to":1}],"fight":"f141"},{"id":"e1506","day":42,"season":2,"sday":12,"kind":"delve_done","imp":1,"text":"The Mercy of Thornwall comes up after 4 days in the Wolf Den. They got all the way to the bottom, mapped 67% of it, found a bone-strewn nest, disarmed 1 trap and came away with 115 silver between them. Counting everyone's digging, the Wolf Den is mostly explored (69%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"wolf_den","days":4,"bottom":true,"rooms":["a bone-strewn nest"],"gold":115},{"id":"e1537","day":43,"season":2,"sday":13,"kind":"road","imp":3,"text":"A cheese the size of a cartwheel comes rolling down the hill beside the road to the Greenwood with half a village after it. Fenwick stops it with a boot and a shout, and is carried to the village on shoulders.","heroes":["h17","h1","h11"],"parties":["p4"],"road":"greenwood~wolf_den","road_rec":"r283"},{"id":"e1549","day":43,"season":2,"sday":13,"kind":"argument","imp":3,"text":"The Mercy of Thornwall spends the evening listening to Fenwick and Brix argue about who ate the last of the cheese.","heroes":["h17","h1"],"parties":["p4"]},{"id":"e1573","day":44,"season":2,"sday":14,"kind":"talent","imp":2,"text":"Quill deals a hand at the Thornwall tavern and somehow everyone else's cards are terrible.","heroes":["h11"],"parties":["p4"],"loc":"thornwall","skill":"card_sharp","wx":"fog"},{"id":"e1589","day":44,"season":2,"sday":14,"kind":"ledger","imp":2,"text":"The week's trade: 14 packs emptied onto counters for 799 silver. Biggest haul: Vex, 126 silver in Ashfen. Back up from the deep: The Green Mercy (3 days in the Sunken Vault), The Azure Gravediggers (8 days in the Ashveil Crypts), The Mercy of Thornwall (4 days in the Wolf Den).","heroes":["h7","h19","h3","h17"],"parties":["p6","p3","p4"]},{"id":"e1600","day":45,"season":2,"sday":15,"kind":"road","imp":3,"text":"A faded sergeant's hat hangs on a peg at the Mile-Warden's hut and Sergeant Pellam says never to touch it. Quill sees it sway in a closed room once, saluting.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ironhaven~thornwall","road_rec":"r286"},{"id":"e1604","day":45,"season":2,"sday":15,"kind":"talent","imp":1,"text":"Brix trades a spare spoon for socks, and the socks for a bag of apples, with three people in one hour.","heroes":["h1"],"parties":["p4"],"loc":"thornwall","skill":"barterer","wx":"fog"},{"id":"e1622","day":46,"season":2,"sday":16,"kind":"road","imp":2,"text":"Quill meets the Fourth-Best Company for the first time on the road to Ironhaven: Captain Mabb, a man called Twice, and a mule called Reputation.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ironhaven~thornwall","traveller":"fourth_best","road_rec":"r289"},{"id":"e1636","day":46,"season":2,"sday":16,"kind":"talent","imp":1,"text":"Fenwick takes on an Ironhaven tavern's eating challenge, free if finished: the whole menu, in order, at speed. The cook comes out to watch. (Can't Stop Now, if anyone's asking.)","heroes":["h17"],"parties":["p4"],"loc":"ironhaven","skill":"cant_stop_now"},{"id":"e1643","day":46,"season":2,"sday":16,"kind":"campfire","imp":2,"text":"Quill's endless cheer finally cracks Brix's silence. Something like a smile appears.","heroes":["h11","h1"],"parties":["p4"],"loc":"ironhaven"},{"id":"e1654","day":47,"season":2,"sday":17,"kind":"road","imp":3,"text":"Philippa Fisk asks Quill to settle a bet about trolls and bridges. Quill settles it, and a fair few other bets while she is at it.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"cragtooth_warren~ironhaven","traveller":"truant_scholars","road_rec":"r292"},{"id":"e1662","day":47,"season":2,"sday":17,"kind":"tarot","imp":2,"text":"Brix lays three cards on a flat stone for The Mercy of Thornwall, with Cragtooth Warren a short walk off in the dark: the Two of Pentacles upside down, the Nine of Pentacles and the Two of Wands. A mixed spread.","heroes":["h17","h1"],"parties":["p4"],"loc":"cragtooth_warren","reading":"r297"},{"id":"e1675","day":48,"season":2,"sday":18,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into Cragtooth Warren, mostly unexplored (22%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1676","day":48,"season":2,"sday":18,"kind":"fight","imp":1,"text":"With Fenwick hitting hardest, the Mercy of Thornwall handles 2 Goblin Archers and a Kobold on floor 1 of Cragtooth Warren. The fight was over the moment Brix's Puppet Strings landed on the goblin archer. Fenwick's Bloodlust kicked in when it counted. Loot: 4 silver each, 2 goblin ears, 1 trinket.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f171","foes":["goblin_archer","kobold","goblin_archer"],"where":"on floor 1 of Cragtooth Warren","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e1692","day":49,"season":2,"sday":19,"kind":"fight","imp":2,"text":"Three Kobold Slingers and a Cave Troll fall to the Mercy of Thornwall on floor 2 of Cragtooth Warren. Somewhere around Quill's Arcane Torrent, the other side stopped believing. Loot: 14 silver each, 4 ore, 8 kobold firepeppers.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f172","foes":["kobold_slinger","cave_troll","kobold_slinger"],"where":"on floor 2 of Cragtooth Warren","won":true,"close":false,"shape":"foe","reworded":-1},{"id":"e1744","day":50,"season":2,"sday":20,"kind":"fight","imp":3,"text":"The Mercy of Thornwall gets the better of 3 Drakes on floor 3 of Cragtooth Warren. The last drake takes off and isn't seen again. The drake went down to Fenwick's Reckless Swing. Loot: 7 fangs & claws, 2 drake scales, 2 drake flanks.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f175","foes":["drake","drake","drake"],"where":"on floor 3 of Cragtooth Warren","won":true,"close":false,"shape":"plain","reworded":-36},{"id":"e1745","day":50,"season":2,"sday":20,"kind":"night","imp":2,"text":"Brix follows strange lights away from the camp in Cragtooth Warren, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1751","day":50,"season":2,"sday":20,"kind":"campfire","imp":1,"text":"Brix admits to being afraid of deep water. Quill doesn't laugh. Quill just nods and takes the watch nearest it.","heroes":["h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1785","day":51,"season":2,"sday":21,"kind":"treasure","imp":3,"text":"Brix kicks over a rotten crate on floor 3 of Cragtooth Warren. Out rolls 27 gold pieces, 57 silver and a gem.","heroes":["h1","h17","h11"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1807","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"Back on floor 3 of Cragtooth Warren, the Mercy of Thornwall beats 4 Drakes. Quill ended it with Arcane Barrage. Without Fenwick's Bloodlust, this goes differently. Loot: 4 drake scales, 11 fangs & claws, 4 drake flanks.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f179","foes":["drake","drake","drake"],"where":"on floor 3 of Cragtooth Warren","won":true,"close":false,"shape":"again","reworded":-6},{"id":"e1808","day":52,"season":2,"sday":22,"kind":"treasure","imp":1,"text":"Quill insists on checking one more passage on floor 3 of Cragtooth Warren, and it opens onto an old adventurers' camp, abandoned in a hurry: 273 silver and an unidentified relic, which goes to Brix.","heroes":["h11","h17","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1850","day":52,"season":2,"sday":22,"kind":"goal_done","imp":4,"text":"GOAL: The Mercy of Thornwall set out to find a relic of the old world, and they have done it, with 8 days to spare. Brix found it. XP: Fenwick +800, Quill +800 (level 14!), Brix +800 (level 14!).","heroes":["h17","h11","h1"],"parties":["p4"],"xp":{"h17":800,"h11":800,"h1":800}},{"id":"e1869","day":53,"season":2,"sday":23,"kind":"boss","imp":5,"text":"At the bottom of Cragtooth Warren, it's over: the Mercy of Thornwall puts an end to 2 Cave Trolls and the Mimic King's Ghost. Fenwick closed it out with Can't Stop Now on the cave troll. Brix's Poker Face had the Mimic King's Ghost briefly confused about whose side it was on. Quill kept everyone standing (107 healed, Rejuvenate doing the heavy lifting). Brix's Magic Missile did the damage (2 times). Loot: 75 silver each, 4 gems, 7 trinkets.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f184","foes":["mimic_king","cave_troll","cave_troll"],"where":"at the bottom of Cragtooth Warren","won":true,"close":false,"shape":"place","reworded":-21},{"id":"e1870","day":53,"season":2,"sday":23,"kind":"treasure","imp":1,"text":"The Mimic King's Ghost's hoard, counted twice by torchlight: 12 gold pieces and 8 silver.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","in_fight":"f184"},{"id":"e1877","day":53,"season":2,"sday":23,"kind":"talent","imp":2,"text":"Fenwick clears three rooms before the party has finished the first. They come back to check they're keeping up. Can't Stop Now all the way, Fenwick insists.","heroes":["h17"],"parties":["p4"],"loc":"cragtooth_warren","skill":"cant_stop_now"},{"id":"e1884","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Quill sits up with Fenwick through a fever, talking about nothing. By morning Fenwick is sitting up and asking for breakfast. Bedside Manner, cast gently, for once.","heroes":["h11","h17"],"parties":["p4"],"loc":"cragtooth_warren","skill":"bedside_manner"},{"id":"e1891","day":53,"season":2,"sday":23,"kind":"big_move","imp":4,"text":"Kragmaw the Tax Collector is dead! It falls to Brix, Quill, Fenwick in Cragtooth Warren. On the table: Quill +335 renown (4th to 1st), Brix +331 (6th to 3rd) and Fenwick +328 (5th to 2nd). The Mercy of Thornwall +447 party renown (holds 1st among the crews).","heroes":["h11","h1","h17"],"parties":["p4"],"cause":"e1854","moves":[{"hero":"h11","gain":335,"from":4,"to":1},{"hero":"h1","gain":331,"from":6,"to":3},{"hero":"h17","gain":328,"from":5,"to":2}],"party_moves":[{"party":"p4","gain":447,"from":1,"to":1}],"fight":"f181"},{"id":"e1893","day":54,"season":2,"sday":24,"kind":"fight","imp":1,"text":"The Mercy of Thornwall, in fine spirits lately, dispatches 2 Drakes on floor 3 of Cragtooth Warren. Fenwick brought Reckless Swing to bear on the drake, and that was the end of it. Loot: 3 drake scales, 3 fangs & claws, 2 drake flanks.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f185","foes":["drake","drake"],"where":"on floor 3 of Cragtooth Warren","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1894","day":54,"season":2,"sday":24,"kind":"treasure","imp":1,"text":"Behind a loose stone on floor 3 of Cragtooth Warren, Fenwick finds 11 gold pieces and 44 silver.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1926","day":55,"season":2,"sday":25,"kind":"delve_done","imp":1,"text":"The Mercy of Thornwall comes up after 8 days in Cragtooth Warren. They got all the way to the bottom, mapped 73% of it, found an old adventurers' camp, abandoned in a hurry, disarmed 1 trap and came away with 9193 silver between them. Counting everyone's digging, Cragtooth Warren is mostly explored (79%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","days":8,"bottom":true,"rooms":["an old adventurers' camp, abandoned in a hurry"],"gold":9193},{"id":"e1953","day":56,"season":2,"sday":26,"kind":"road","imp":4,"text":"Mags Halloran spars with Brix at the roadside and ends up on her back. She laughs for the first time anyone remembers.","heroes":["h1","h11","h17"],"parties":["p4"],"road":"cragtooth_warren~ironhaven","traveller":"mags","road_rec":"r366"},{"id":"e1956","day":56,"season":2,"sday":26,"kind":"bounty","imp":2,"text":"The Mercy of Thornwall cashes in a season's worth of trophies at the Ironhaven guild: about 92 silver a head.","heroes":["h17"],"parties":["p4"],"loc":"ironhaven","amount":92},{"id":"e2008","day":57,"season":2,"sday":27,"kind":"road","imp":3,"text":"Quill hears the Lantern Lady say that she cannot remember her own name, only that it is written somewhere. Quill promises to look.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ironhaven~thornwall","traveller":"lantern_lady","road_rec":"r377"},{"id":"e2013","day":57,"season":2,"sday":27,"kind":"campfire","imp":2,"text":"Fenwick carries Quill's pack for the last mile without being asked.","heroes":["h17","h11"],"parties":["p4"],"loc":"ironhaven"},{"id":"e2043","day":58,"season":2,"sday":28,"kind":"campfire","imp":1,"text":"Brix wakes up to find Quill has already made the tea. Exactly how Brix likes it.","heroes":["h1","h11"],"parties":["p4"],"loc":"thornwall"},{"id":"e2046","day":58,"season":2,"sday":28,"kind":"ledger","imp":2,"text":"THE LEDGER: 18 hauls sold this week, 2,600 silver in all. Biggest haul: Fenwick, 884 silver in Ironhaven. Back up from the deep: The Mercy of Thornwall (8 days in Cragtooth Warren), Amber Banner (2 days in the Sunken Vault).","heroes":["h17","h18"],"parties":["p4","p2"]},{"id":"e2059","day":59,"season":2,"sday":29,"kind":"road","imp":3,"text":"Lady Perpetua Vane presses a letter of introduction into Brix's hand, sealed in wax with a lopsided crest. 'Doors open for this,' she says, and means it.","heroes":["h1","h11","h17"],"parties":["p4"],"road":"carrbridge~thornwall","traveller":"perpetua","road_rec":"r389"},{"id":"e2099","day":60,"season":2,"sday":30,"kind":"road","imp":3,"text":"A beggar on the road to Bleakmarsh hums a tune that Quill and Brix both seem to know without knowing how. They finish it together, and the beggar is gone.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"bleakmarsh~carrbridge","road_rec":"r395"},{"id":"e2106","day":60,"season":2,"sday":30,"kind":"meet","imp":2,"text":"The Mercy of Thornwall warns The Newts of Ashfen about what's lurking in Bleakmarsh. The Newts of Ashfen pretend to already know.","heroes":["h17","h11","h1","h13","h7"],"parties":["p4","p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2107","day":60,"season":2,"sday":30,"kind":"talent","imp":1,"text":"Quill plays a pedlar for his boots at a roadside halt, wins them, and gives them back. Mostly. Card Sharp all the way, Quill insists.","heroes":["h11"],"parties":["p4"],"loc":"bleakmarsh","skill":"card_sharp","wx":"rain"},{"id":"e2108","day":60,"season":2,"sday":30,"kind":"talent","imp":2,"text":"Fenwick bets Brix a silver that the next cart will be pulled by a mule. It's a mule. Brix pays up, grumbling.","heroes":["h17","h1"],"parties":["p4"],"loc":"bleakmarsh","skill":"gambler","wx":"rain"},{"id":"e2127","day":60,"season":2,"sday":30,"kind":"season_end","imp":5,"text":"Season 2 ends. Fenwick is Hero of the Season with 681 renown. The Mercy of Thornwall finishes as the top party.","heroes":["h17","h11","h1"],"parties":["p4"]},{"id":"e2128","day":60,"season":2,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Mercy of Thornwall (Fenwick, Quill and Brix) ends season 2 as the league's best crew, 972 party renown. Their season: 3 bosses, 12 fights won and 7 floors explored.","heroes":["h17","h11","h1"],"parties":["p4"]},{"id":"e2166","day":61,"season":3,"sday":1,"kind":"contract","imp":2,"text":"The Mercy of Thornwall takes a job that isn't on the board in Ironhaven: somebody's very quiet cousin, to Ashfen. The pay is very good. That's the worrying part.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ironhaven"},{"id":"e2167","day":61,"season":3,"sday":1,"kind":"escort","imp":1,"text":"The Mercy of Thornwall checks somebody's very quiet cousin one last time in the Ironhaven yard and heads out for Carrbridge.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ironhaven"},{"id":"e2177","day":61,"season":3,"sday":1,"kind":"journey","imp":2,"text":"The Black Vanguard and The Mercy of Thornwall walk to Carrbridge together. Someone brings up old scars. Someone always does.","heroes":["h12","h8","h6","h17","h11","h1"],"parties":["p5","p4"]},{"id":"e2200","day":62,"season":3,"sday":2,"kind":"escort","imp":1,"text":"A buyer at a crossroads on the road to Ashfen offers good silver for the cargo, on the spot. The Mercy of Thornwall says no. It isn't theirs to sell.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"carrbridge"},{"id":"e2210","day":62,"season":3,"sday":2,"kind":"meet","imp":1,"text":"The Green Mercy and The Mercy of Thornwall pass on the road between Ashfen and Carrbridge. Barnaby shares directions.","heroes":["h19","h20","h10","h16","h17","h11","h1"],"parties":["p6","p4"],"loc":"ashfen","wx":"rain"},{"id":"e2221","day":63,"season":3,"sday":3,"kind":"road","imp":3,"text":"A wyvern circles the far ridge beyond the road to Ashfen for an hour, small as a hawk and just as unbothered. Brix sketches it on a scrap.","heroes":["h1","h11","h17"],"parties":["p4"],"road":"ashfen~carrbridge","road_rec":"r425"},{"id":"e2224","day":63,"season":3,"sday":3,"kind":"contract","imp":4,"text":"CAUGHT: the watch in Ashfen opens somebody's very quiet cousin. The Mercy of Thornwall spends the night in the cells and pays 30 silver each to get out.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashfen","wx":"storm"},{"id":"e2253","day":64,"season":3,"sday":4,"kind":"jail_wait","imp":1,"text":"The Mercy of Thornwall waits around Ashfen for Quill to get out of the cells.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashfen","wx":"storm"},{"id":"e2284","day":65,"season":3,"sday":5,"kind":"jail_wait","imp":1,"text":"The Mercy of Thornwall waits around Ashfen for Brix to get out of the cells.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashfen","wx":"storm"},{"id":"e2316","day":66,"season":3,"sday":6,"kind":"night","imp":1,"text":"Something small and clever gets into The Mercy of Thornwall's camp in the Ashveil Crypts overnight. Fenwick wakes up 9 silver and 2 rations lighter.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e2333","day":67,"season":3,"sday":7,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into the Ashveil Crypts, partly explored (37%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e2334","day":67,"season":3,"sday":7,"kind":"fight","imp":1,"text":"With Fenwick keeping everyone up, the Mercy of Thornwall sees off 2 Skeletons and a Giant Rat on floor 1 of the Ashveil Crypts. Fenwick stepped in with Reckless Swing, and the skeleton was on the ground. Brix pulled a friend out of trouble and went back in for more. Loot: 9 bones, a rat haunch. Fenwick, who has been afraid of the dead since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f220","foes":["skeleton","giant_rat","skeleton"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-34,"wx":"storm"},{"id":"e2366","day":67,"season":3,"sday":7,"kind":"talent","imp":2,"text":"Brix sorts a pouch of grave dust by quality. It is, apparently, a thing you can do. Grave Sense, cast gently, for once.","heroes":["h1"],"parties":["p4"],"loc":"ashveil_crypts","skill":"grave_sense","wx":"storm"},{"id":"e2367","day":67,"season":3,"sday":7,"kind":"campfire","imp":2,"text":"Brix replays the last fight for Quill blow by blow. In this version, both are heroes. Both were.","heroes":["h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e2380","day":68,"season":3,"sday":8,"kind":"fight","imp":2,"text":"On floor 2 of the Ashveil Crypts, the Mercy of Thornwall squares up to 3 Skeleton Archers and a Skeleton and carries the day. The fight turned on Brix's Magic Missile. Raise Skeleton, from Quill, at exactly the right moment. Loot: 13 bones, 2 trinkets.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f225","foes":["skeleton_archer","skeleton_archer","skeleton_archer"],"where":"on floor 2 of The Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-27,"wx":"rain"},{"id":"e2381","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"It's raining sideways and Brix gets the fire lit on the second spark. The crew cheers like it's a boss kill. Firekeeper, the guild calls it.","heroes":["h1"],"parties":["p4"],"loc":"ashveil_crypts","skill":"firekeeper","wx":"rain"},{"id":"e2402","day":69,"season":3,"sday":9,"kind":"ambush","imp":2,"text":"The Mercy of Thornwall gets the better of the Bounty Hunters' Captain and Bounty Hunter in the Ashveil Crypts, sent for the price on Quill's head. Quill's Raise Skeleton brought help, and the help earned its keep. Fenwick's Bloodlust kicked in when it counted. Loot: 34 silver each, 4 stolen goods, 3 bandit sausages.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f227","foes":["bandit_captain","bandit"],"where":"in The Ashveil Crypts, sent for the price on Quill's head","won":true,"close":false,"shape":"plain","reworded":-11,"wx":"rain"},{"id":"e2404","day":69,"season":3,"sday":9,"kind":"fight","imp":2,"text":"The Mercy of Thornwall, in fine spirits lately, beats 2 Risen Dead and a Wraith on floor 3 of the Ashveil Crypts. Fenwick ended it with Frost Brand. Loot: 2 grave dust, 2 crypt-caps, 2 ectoplasm.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f228","foes":["zombie","wraith","zombie"],"where":"on floor 3 of The Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"rain"},{"id":"e2429","day":69,"season":3,"sday":9,"kind":"campfire","imp":1,"text":"Brix and Quill take the late watch together and argue happily about the best road to Ironhaven.","heroes":["h1","h11"],"parties":["p4"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e2438","day":70,"season":3,"sday":10,"kind":"fight","imp":1,"text":"Two Wraiths and a Bone Construct are waiting on floor 4 of the Ashveil Crypts, and the Mercy of Thornwall makes short work of them. Quill had the last word, and the word was Force Bolt. Loot: 4 wraith-frost, 13 bones, 4 ectoplasm.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f232","foes":["wraith","bone_construct","wraith"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-24},{"id":"e2439","day":70,"season":3,"sday":10,"kind":"artifact","imp":3,"text":"Brix pockets a purse that is always a little fuller than it should be in the Ashveil Crypts. Brix feels stronger already.","heroes":["h1"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e2484","day":71,"season":3,"sday":11,"kind":"boss","imp":5,"text":"Fenwick holds the line while the Mercy of Thornwall kills 2 Bone Constructs and Vessimir the Unburied's Usurper at the bottom of the Ashveil Crypts. Once Quill's Prepared for This was on Vessimir the Unburied's Usurper, the rest was arithmetic. Magic Missile left Brix's hands and Vessimir the Unburied's Usurper was done. Battle Cry did more for this fight than the scoreboard shows. That was Fenwick. Brix landed 2 crushing blows, mostly with Poker Face. Stormwright's Gauntlet crackled and Brix's blow landed like thunder. \"Fine,\" says Brix. Loot: 85 silver each, 9 ectoplasm, 8 grave dust.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","fight":"f236","foes":["necromancer","bone_construct","bone_construct"],"where":"at the bottom of The Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-29},{"id":"e2485","day":71,"season":3,"sday":11,"kind":"treasure","imp":2,"text":"Vessimir the Unburied's Usurper's hoard, counted twice by torchlight: 18 gold pieces and 8 silver.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","in_fight":"f236"},{"id":"e2486","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Quill warms the crew's socks with a snap of the fingers. Nothing has ever been more appreciated.","heroes":["h11"],"parties":["p4"],"loc":"ashveil_crypts","skill":"cantrips"},{"id":"e2509","day":71,"season":3,"sday":11,"kind":"campfire","imp":1,"text":"Quill slips Duke a sausage under the table. Fenwick sees, and decides Quill is all right.","heroes":["h17","h11"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e2514","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Mercy of Thornwall sets their sights for the season: to earn 5,600 silver between them before the season ends.","heroes":["h17","h11","h1"],"parties":["p4"]},{"id":"e2520","day":71,"season":3,"sday":11,"kind":"big_move","imp":4,"text":"Fenwick holds the line while the Mercy of Thornwall kills 2 Bone Constructs and Vessimir the Unburied's Usurper at the bottom of the Ashveil Crypts. On the table: Fenwick +121 renown (8th to 3rd), Brix +120 (5th to 2nd) and Quill +116 (2nd to 1st). The Mercy of Thornwall +188 party renown (2nd to 1st among the crews).","heroes":["h17","h1","h11"],"parties":["p4"],"cause":"e2484","moves":[{"hero":"h17","gain":121,"from":8,"to":3},{"hero":"h1","gain":120,"from":5,"to":2},{"hero":"h11","gain":116,"from":2,"to":1}],"party_moves":[{"party":"p4","gain":188,"from":2,"to":1}],"fight":"f236"},{"id":"e2536","day":72,"season":3,"sday":12,"kind":"delve_done","imp":1,"text":"The Mercy of Thornwall comes up after 6 days in the Ashveil Crypts. They got all the way to the bottom, mapped 48% of it, disarmed 1 trap and came away with 563 silver between them. Counting everyone's digging, the Ashveil Crypts is partly explored (55%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","days":6,"bottom":true,"rooms":[],"gold":563,"wx":"fog"},{"id":"e2537","day":72,"season":3,"sday":12,"kind":"night","imp":2,"text":"A hooded stranger shares The Mercy of Thornwall's fire outside the Ashveil Crypts, eats half the stew, and says something very specific about Frostspire before leaving.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2556","day":73,"season":3,"sday":13,"kind":"road","imp":2,"text":"Little Ansel of the Jingling Pilgrims presses a paper flower on Quill for the first time, and then a second one, in case the first is lost.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ashfen~ashveil_crypts","traveller":"dancing_pilgrims","road_rec":"r479"},{"id":"e2575","day":73,"season":3,"sday":13,"kind":"talent","imp":2,"text":"Brix bluffs a whole Ashfen table off a pair of twos. Nobody asks to see them; nobody asks anything. Brix puts it down to Poker Face.","heroes":["h1"],"parties":["p4"],"loc":"ashfen","skill":"poker_face","wx":"fog"},{"id":"e2588","day":74,"season":3,"sday":14,"kind":"curse","imp":4,"text":"Something is wrong with The Mercy of Thornwall. Since Brix picked up the Red Purse, nobody trusts anybody, and Brix won't put it down.","heroes":["h1"],"parties":["p4"],"loc":"ashfen","wx":"fog"},{"id":"e2596","day":74,"season":3,"sday":14,"kind":"road","imp":3,"text":"Captain Dorrit Salt swears to Quill she has heard a rumour of something dreadful near Thornmere Ruins, and a pub that serves the best rum on land.","heroes":["h11","h1","h17"],"parties":["p4"],"road":"ashfen~carrbridge","traveller":"salt","road_rec":"r484"},{"id":"e2619","day":74,"season":3,"sday":14,"kind":"talent","imp":1,"text":"Quill walks the whole day with a book open, reading about something with too many teeth. Brix steers. Somebody asks how. 'Prepared for This,' says Quill.","heroes":["h11","h1"],"parties":["p4"],"loc":"ashfen","skill":"prepared_for_this","wx":"fog"},{"id":"e2628","day":74,"season":3,"sday":14,"kind":"campfire","imp":2,"text":"Brix and Quill have a two-hour argument about whether a goblin could beat a goose. It is never resolved.","heroes":["h1","h11"],"parties":["p4"],"loc":"ashfen","wx":"fog"},{"id":"e2633","day":74,"season":3,"sday":14,"kind":"ledger","imp":2,"text":"Counters and coin this week: 16 sales, 1,962 silver changing hands. Biggest haul: Hazel, 500 silver in Carrbridge. Back up from the deep: The Mercy of Thornwall (6 days in the Ashveil Crypts), The Black Vanguard (9 days in Thornmere Ruins).","heroes":["h8","h17","h12"],"parties":["p4","p5"]},{"id":"e2661","day":75,"season":3,"sday":15,"kind":"talent","imp":1,"text":"Quill makes a bunch of flowers bloom for a Carrbridge child. The child's grandmother pays in tart.","heroes":["h11"],"parties":["p4"],"loc":"carrbridge","skill":"cantrips","wx":"rain"},{"id":"e2662","day":75,"season":3,"sday":15,"kind":"talent","imp":1,"text":"Fenwick drills the Carrbridge militia for an afternoon. The militia sends round a thank-you ham.","heroes":["h17"],"parties":["p4"],"loc":"carrbridge","skill":"drillmaster","wx":"rain"},{"id":"e2749","day":77,"season":3,"sday":17,"kind":"campfire","imp":1,"text":"Duke the dog won't sleep unless Brix is in sight. Nobody can explain it.","heroes":["h17","h1"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2768","day":78,"season":3,"sday":18,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into Cragtooth Warren, mostly unexplored (28%), map in hand.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e2769","day":78,"season":3,"sday":18,"kind":"fight","imp":1,"text":"On floor 1 of Cragtooth Warren, the Mercy of Thornwall dispatches 2 Kobolds and a Goblin Archer. Fenwick stepped in with Unstoppable, and the kobold was on the ground. Loot: 3 silver each, 3 ore, a kobold firepepper.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f260","foes":["kobold","kobold","goblin_archer"],"where":"on floor 1 of Cragtooth Warren","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e2771","day":78,"season":3,"sday":18,"kind":"night","imp":2,"text":"Something small and clever gets into The Mercy of Thornwall's camp in Cragtooth Warren overnight. Fenwick wakes up 9 silver and 1 ration lighter.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e2782","day":78,"season":3,"sday":18,"kind":"tarot","imp":2,"text":"On the last night before Cragtooth Warren, Brix spreads a cloak by the fire and reads the Pressed-Leaf Tarot for the whole of The Mercy of Thornwall: the Page of Pentacles, the Four of Cups and Justice. Some good, some not.","heroes":["h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","reading":"r505"},{"id":"e2784","day":78,"season":3,"sday":18,"kind":"talent","imp":1,"text":"Brix uses Stormwright's Gauntlet to lift the hot pot off the fire. The pot dents.","heroes":["h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e2792","day":79,"season":3,"sday":19,"kind":"treasure","imp":3,"text":"Fenwick jimmies open a chest on floor 2 of Cragtooth Warren: 4 gold pieces and 5 silver.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e2813","day":79,"season":3,"sday":19,"kind":"campfire","imp":1,"text":"Quill and Fenwick take the late watch together and argue happily about the best road to Ironhaven.","heroes":["h11","h17"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e2826","day":80,"season":3,"sday":20,"kind":"treasure","imp":1,"text":"Mapping floor 2 of Cragtooth Warren, Brix finds a crystal grotto. Inside: 1 gold piece, 30 silver and a gem.","heroes":["h1","h17","h11"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2845","day":80,"season":3,"sday":20,"kind":"gift","imp":2,"text":"By the fire, Brix quietly hands Fenwick a Bone Flute. Fenwick pockets it like it's treasure.","heroes":["h1","h17"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2851","day":81,"season":3,"sday":21,"kind":"curse","imp":3,"text":"Brix still won't put down the Red Purse. 7 days now. The others have stopped asking.","heroes":["h1"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2867","day":81,"season":3,"sday":21,"kind":"treasure","imp":1,"text":"Behind a sealed door with the seal unbroken on floor 3 of Cragtooth Warren, nobody had been in years. Brix comes out with 38 silver, a gem and a troll haunch.","heroes":["h1","h17","h11"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2897","day":82,"season":3,"sday":22,"kind":"skim","imp":2,"text":"Fenwick quietly pockets an extra 164 silver while The Mercy of Thornwall counts the rest. Nobody notices.","heroes":["h17"],"parties":["p4"],"loc":"cragtooth_warren","in_fight":"f263","wx":"rain"},{"id":"e2898","day":82,"season":3,"sday":22,"kind":"boss","imp":5,"text":"Quill keeps everyone up while the Mercy of Thornwall finishes off 2 Drakes and the Mimic King's Second Coming at the bottom of Cragtooth Warren. The last drake doesn't stay to see the end. Fenwick brought Unstoppable to bear on the drake, and that was the end of it. The Mimic King's Second Coming went down to Brix's Poker Face. Quill's Prepared for This turned the fight. Brix kept two of them busy so nobody else had to. Loot: 74 silver each, 4 gems, 11 trinkets.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f263","foes":["mimic_king","drake","drake"],"where":"at the bottom of Cragtooth Warren","won":true,"close":false,"shape":"hero","reworded":-59,"wx":"rain"},{"id":"e2899","day":82,"season":3,"sday":22,"kind":"treasure","imp":1,"text":"The Mimic King's Second Coming's hoard, counted twice by torchlight: 16 gold pieces and 4 silver.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","in_fight":"f263","wx":"rain"},{"id":"e2909","day":82,"season":3,"sday":22,"kind":"gift","imp":2,"text":"Brix admired Quill's Two-Headed Toll Coin one too many times. Now it's Brix's.","heroes":["h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2920","day":82,"season":3,"sday":22,"kind":"big_move","imp":4,"text":"Quill keeps everyone up while the Mercy of Thornwall finishes off 2 Drakes and the Mimic King's Second Coming at the bottom of Cragtooth Warren. On the table: Fenwick +110 renown (4th to 2nd), Brix +107 (5th to 3rd) and Quill +95 (holds 4th). The Mercy of Thornwall +169 party renown (holds 1st among the crews).","heroes":["h17","h1","h11"],"parties":["p4"],"cause":"e2898","moves":[{"hero":"h17","gain":110,"from":4,"to":2},{"hero":"h1","gain":107,"from":5,"to":3},{"hero":"h11","gain":95,"from":2,"to":4}],"party_moves":[{"party":"p4","gain":169,"from":1,"to":1}],"fight":"f263"},{"id":"e2923","day":83,"season":3,"sday":23,"kind":"treasure","imp":3,"text":"Quill insists on checking one more passage on floor 3 of Cragtooth Warren, and it opens onto an abandoned dig with the picks still in the wall: 1 gold piece and 19 silver.","heroes":["h11","h17","h1"],"parties":["p4"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e2973","day":84,"season":3,"sday":24,"kind":"treasure","imp":2,"text":"Fenwick kicks over a rotten crate on floor 3 of Cragtooth Warren. Out rolls 139 silver and a troll haunch.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e2987","day":84,"season":3,"sday":24,"kind":"argument","imp":4,"text":"Fenwick and Brix have had the same argument three times now. This time Fenwick just walks away mid-sentence, which is worse. The Mercy of Thornwall is splitting into camps.","heroes":["h17","h1"],"parties":["p4"]},{"id":"e2995","day":85,"season":3,"sday":25,"kind":"delve_done","imp":3,"text":"The Mercy of Thornwall comes up after 8 days in Cragtooth Warren. They got all the way to the bottom, mapped 71% of it, found a crystal grotto, a sealed door with the seal unbroken and an abandoned dig with the picks still in the wall, disarmed 1 trap and came away with 833 silver between them. Counting everyone's digging, Cragtooth Warren is mostly explored (86%).","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"cragtooth_warren","days":8,"bottom":true,"rooms":["a crystal grotto","a sealed door with the seal unbroken"],"gold":833},{"id":"e3070","day":87,"season":3,"sday":27,"kind":"party_life","imp":1,"text":"Fenwick rides ahead, rides back, rides ahead again. Quill and Brix are not amused.","heroes":["h17","h11","h1"],"parties":["p4"],"loc":"ironhaven"},{"id":"e3088","day":88,"season":3,"sday":28,"kind":"curse","imp":2,"text":"Another bad night for The Mercy of Thornwall. The Red Purse hums when Brix sleeps. Nobody else sleeps at all.","heroes":["h1"],"parties":["p4"],"loc":"ironhaven"},{"id":"e3089","day":88,"season":3,"sday":28,"kind":"curse","imp":5,"text":"Prelate Gaudin takes the Red Purse from Brix's shaking hands, says some very old words over it, and breaks it. 60 silver, and worth every coin.","heroes":["h1"],"parties":["p4"],"loc":"ironhaven"},{"id":"e3101","day":88,"season":3,"sday":28,"kind":"vow","imp":2,"text":"Ottoline brings an unfinished vow into The Mercy of Thornwall: to die rich. They take it on.","heroes":["h14"],"parties":["p4"]},{"id":"e3102","day":88,"season":3,"sday":28,"kind":"party_join","imp":3,"text":"Ottoline joins The Mercy of Thornwall over drinks in Veldrock. That makes 4.","heroes":["h14","h17","h11","h1"],"parties":["p4"],"loc":"veldrock","wx":"fog"},{"id":"e3108","day":88,"season":3,"sday":28,"kind":"argument","imp":2,"text":"Ottoline and Fenwick are not speaking. It's about the ethics of looting bodies. It's never really about the ethics of looting bodies.","heroes":["h14","h17"],"parties":["p4"]},{"id":"e3111","day":88,"season":3,"sday":28,"kind":"goal_done","imp":4,"text":"GOAL: The Mercy of Thornwall set out to earn 5,600 silver between them before the season ends, and they have done it, with 2 days to spare. XP: Fenwick +800, Quill +800 (level 19!), Brix +840, Ottoline +800.","heroes":["h17","h11","h1","h14"],"parties":["p4"],"xp":{"h17":800,"h11":800,"h1":840,"h14":800}},{"id":"e3141","day":89,"season":3,"sday":29,"kind":"meet","imp":2,"text":"The Mercy of Thornwall runs into The Newts of Ashfen in Emberdeep. Stories are exchanged, most of them exaggerated.","heroes":["h17","h11","h1","h14","h13","h7"],"parties":["p4","p1"],"loc":"emberdeep","wx":"snow"},{"id":"e3147","day":89,"season":3,"sday":29,"kind":"tarot","imp":2,"text":"The Mercy of Thornwall sit in a ring while Brix turns the Pressed-Leaf Tarot for all of them before Emberdeep: the Seven of Cups, the Six of Pentacles upside down and the King of Swords. Brix gathers the cards up quickly.","heroes":["h17","h14"],"parties":["p4"],"loc":"emberdeep","reading":"r592","wx":"snow"},{"id":"e3151","day":89,"season":3,"sday":29,"kind":"talent","imp":2,"text":"Fenwick tries to read Brix's face over a hand of cards for an hour, gives up, and asks to see the cards instead.","heroes":["h1","h17"],"parties":["p4"],"loc":"emberdeep","skill":"poker_face","wx":"snow"},{"id":"e3167","day":90,"season":3,"sday":30,"kind":"delve","imp":1,"text":"The Mercy of Thornwall descends into Emberdeep, barely touched (9%).","heroes":["h17","h11","h1","h14"],"parties":["p4"],"loc":"emberdeep","wx":"snow"},{"id":"e3170","day":90,"season":3,"sday":30,"kind":"fight","imp":2,"text":"The Mercy of Thornwall makes short work of 2 Salamanders and 2 Fire Elementals on floor 1 of Emberdeep. Ottoline's Sky Lance finished the fight. Loot: 5 ember cores, 1 drake scale, 4 salamander tails.","heroes":["h17","h11","h1","h14"],"parties":["p4"],"loc":"emberdeep","fight":"f279","foes":["salamander","fire_elemental","fire_elemental"],"where":"on floor 1 of Emberdeep","won":true,"close":false,"shape":"plain","wx":"snow"},{"id":"e3171","day":90,"season":3,"sday":30,"kind":"ability","imp":2,"text":"Ottoline sits on a stone after Emberdeep and scratches the fight into the back of her shield in tiny marks: who, where, how. She finds the mistake, and feels better for finding it.","heroes":["h14"],"parties":["p4"],"loc":"emberdeep","skill":"keeps_a_tally","sk":"Keeps a Tally","rule":true,"wx":"snow"},{"id":"e3174","day":90,"season":3,"sday":30,"kind":"meet","imp":1,"text":"Fenwick and Duren swap stories in Emberdeep while The Mercy of Thornwall and The Azure Gravediggers swap rumours.","heroes":["h17","h11","h1","h14","h3","h15","h5","h9"],"parties":["p4","p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3187","day":90,"season":3,"sday":30,"kind":"talent","imp":1,"text":"Fenwick draws every monster the party knows in the dirt and circles the soft bits.","heroes":["h17"],"parties":["p4"],"loc":"emberdeep","skill":"go_for_the_throat","wx":"snow"},{"id":"e3195","day":90,"season":3,"sday":30,"kind":"delve_done","imp":1,"text":"The Mercy of Thornwall comes up after 1 day in Emberdeep. They got down to floor 1 and disarmed 1 trap. Emberdeep is now mostly unexplored (13%).","heroes":["h17","h11","h1","h14"],"parties":["p4"],"loc":"emberdeep","days":1,"bottom":false,"rooms":[],"gold":0,"wx":"snow"},{"id":"e3196","day":90,"season":3,"sday":30,"kind":"ability","imp":1,"text":"Quill watches Ottoline walk out of Emberdeep wearing 17 silver and a chunk of ore like a badly planned necklace.","heroes":["h14","h11"],"parties":["p4"],"loc":"emberdeep","skill":"lodestone_hands","sk":"Lodestone Hands","rule":true,"wx":"snow"},{"id":"e3204","day":90,"season":3,"sday":30,"kind":"season_end","imp":5,"text":"Season 3 ends. Ottoline is Hero of the Season with 546 renown. The Mercy of Thornwall finishes as the top party.","heroes":["h14","h17","h11","h1"],"parties":["p4"]},{"id":"e3205","day":90,"season":3,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Mercy of Thornwall (Fenwick, Quill, Brix and Ottoline) ends season 3 as the league's best crew, 769 party renown. Their season: 2 bosses, 9 fights won and 8 floors explored.","heroes":["h17","h11","h1","h14"],"parties":["p4"]},{"id":"e3208","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Newts of Ashfen, to share every coin (sworn in season 2); Amber Banner, to die rich (sworn in season 2); The Mercy of Thornwall, to keep the peace: never draw first on another hero (sworn in season 2); The Mercy of Thornwall, to die rich (sworn in season 2); The Black Vanguard, never to retreat (sworn in season 2); The Green Mercy, to keep the peace: never draw first on another hero (sworn in season 1); Vex, to keep the peace: never draw first on another hero (sworn in season 1). Every one of them held.","heroes":["h7"],"parties":["p1","p2","p4","p5","p6"]}],"roles":{"h14":"Spellcaster","h11":"Healer","h1":"Scout","h17":"Leader · Berserker"},"quest":{"what":"Delve","where":"Emberdeep","why":"racing The Newts of Ashfen to the boss: about 19 silver a day each, risk real; the season goal: to earn 5,600 silver between them before the season ends","floor":0,"floors":5},"tactics":{"front":["h17"],"back":["h11","h1","h14"],"plan":"Fenwick holds the front; Quill, Brix and Ottoline cast from behind; Quill keeps everyone standing.","traits":{"boldness":0.14,"risk":0.49,"greed":0.34,"sociability":-0.1,"honor":-0.32,"curiosity":-0.19,"temper":-0.02,"loyalty":-0.18},"mix":"3 casters, 1 blade","notes":["One shield. If Fenwick falls, the line goes with them.","Spell-heavy: they win fast or not at all."],"style":["reckless","silver-hungry","spell-heavy"],"skills":[{"label":"Damage","skills":[{"hero":"h17","id":"reckless_swing","name":"Reckless Swing","desc":"All in. Every time.","tags":["rage"],"rank":3,"uses":31},{"hero":"h14","id":"lightning_bolt","name":"Lightning Bolt","desc":"Straight through the armour, smelling of rain.","tags":["storm"],"rank":3,"uses":28},{"hero":"h1","id":"magic_missile","name":"Magic Missile","desc":"Three darts of light. Usually all three land.","tags":["arcane"],"rank":2,"uses":25},{"hero":"h1","id":"poker_face","name":"Poker Face","desc":"Nobody has ever known what they were holding. Including, once, them.","tags":[],"rank":1,"uses":22},{"hero":"h1","id":"puppet_strings","name":"Puppet Strings","desc":"A suggestion, whispered, obeyed.","tags":["stealth"],"rank":3,"uses":19},{"hero":"h14","id":"pinpoint_bolt","name":"Pinpoint Bolt","desc":"Hits the buckle. Then everything the buckle was holding.","tags":["storm","crit"],"rank":2,"uses":15},{"hero":"h14","id":"heavens_aim","name":"Heaven's Aim","desc":"Waits for the cloud to line up. Then stops waiting.","tags":["crit","storm"],"rank":3,"uses":14},{"hero":"h11","id":"force_bolt","name":"Force Bolt","desc":"An invisible fist, thrown from across the room.","tags":["arcane"],"rank":1,"uses":13},{"hero":"h14","id":"sky_lance","name":"Sky Lance","desc":"Picks one target and drops the sky on it.","tags":["storm","crit"],"rank":1,"uses":9},{"hero":"h17","id":"frost_brand","name":"Frost Brand","desc":"The edge rimes with ice.","tags":["ice"],"rank":1,"uses":8},{"hero":"h14","id":"thunderclap","name":"Thunderclap","desc":"BOOM.","tags":["storm"],"rank":1,"uses":7},{"hero":"h17","id":"unstoppable","name":"Unstoppable","desc":"Doesn't stop for walls.","tags":["rage"],"rank":1,"uses":3},{"hero":"h11","id":"arcane_torrent","name":"Arcane Torrent","desc":"Opens the book and lets it out.","tags":["arcane"],"rank":3,"uses":3},{"hero":"h17","id":"twin_strike","name":"Twin Strike","desc":"Two cuts, one breath.","tags":[],"rank":1,"uses":1},{"hero":"h11","id":"magic_missile","name":"Magic Missile","desc":"Three darts of light. Usually all three land.","tags":["arcane"],"rank":1,"uses":1},{"hero":"h11","id":"arcane_barrage","name":"Arcane Barrage","desc":"Magic Missile, but with a grudge.","tags":["arcane"],"rank":2,"uses":1},{"hero":"h14","id":"expose_weakness","name":"Expose Weakness","desc":"Points out the soft bit, loudly.","tags":["lore","crit"],"rank":1,"uses":1}]},{"label":"Healing","skills":[{"hero":"h11","id":"rejuvenate","name":"Rejuvenate","desc":"Green light washes over the party.","tags":["nature","heal"],"rank":2,"uses":10}]},{"label":"Defence","skills":[{"hero":"h11","id":"arcane_shield","name":"Arcane Shield","desc":"A shimmer over the whole party.","tags":["arcane","guard"],"rank":2,"uses":11},{"hero":"h17","id":"shield_wall","name":"Shield Wall","desc":"Plants their feet and dares anyone to try.","tags":["guard"],"rank":1,"uses":8},{"hero":"h17","id":"battle_cry","name":"Battle Cry","desc":"Bellows something inspiring and mostly vowels. Everyone swings harder.","tags":["command","rage"],"rank":1,"uses":7}]},{"label":"Tricks","skills":[{"hero":"h17","id":"bloodlust","name":"Bloodlust","desc":"Drinks deep from every kill.","tags":["rage"],"rank":3,"uses":27},{"hero":"h11","id":"raise_skeleton","name":"Raise Skeleton","desc":"A friend from the floor.","tags":["death"],"rank":1,"uses":22},{"hero":"h14","id":"phantasm","name":"Phantasm","desc":"A horror only the monster can see.","tags":["stealth"],"rank":1,"uses":16},{"hero":"h17","id":"cant_stop_now","name":"Can't Stop Now","desc":"Every fallen foe is a warm-up for the next one.","tags":[],"rank":1,"uses":15},{"hero":"h14","id":"sleet_squall","name":"Sleet Squall","desc":"Freezing rain on every foe.","tags":["ice","storm"],"rank":2,"uses":11},{"hero":"h11","id":"prepared_for_this","name":"Prepared for This","desc":"Has been saving one spell for exactly this monster. Has notes.","tags":[],"rank":1,"uses":6},{"hero":"h17","id":"captains_call","name":"Captain's Call","desc":"When one falls, the rest hit harder for them.","tags":["command","rage"],"rank":1,"uses":1},{"hero":"h17","id":"frenzy","name":"Frenzy","desc":"When a friend falls, sees red.","tags":["rage"],"rank":3,"uses":1},{"hero":"h1","id":"mass_suggestion","name":"Mass Suggestion","desc":"Everyone agrees with them. Even the ones holding axes.","tags":["stealth"],"rank":1,"uses":1},{"hero":"h17","id":"go_for_the_throat","name":"Go for the Throat","desc":"Points at the weak spot and roars about it.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"mirror_image","name":"Mirror Image","desc":"There are three of them. The monster picks wrong.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h1","id":"vanish","name":"Vanish","desc":"Was there. Is not.","tags":["stealth"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h1","id":"blink","name":"Blink","desc":"Is suddenly two feet to the left.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h1","id":"quick_feet","name":"Quick Feet","desc":"First in, first out.","tags":["travel","stealth"],"rank":1,"uses":0},{"hero":"h14","id":"storm_focus","name":"Storm Focus","desc":"Calm in the middle. Deadly at the edges.","tags":["storm","crit"],"rank":1,"uses":0},{"hero":"h14","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h17","id":"knot_tying","name":"Knotwork","desc":"Knows forty knots and when to use thirty-nine of them.","tags":["travel","craft"],"rank":1,"uses":0},{"hero":"h17","id":"gambler","name":"Gambler","desc":"Dice nights are profitable. Usually.","tags":[],"rank":1,"uses":0},{"hero":"h17","id":"drillmaster","name":"Drillmaster","desc":"Drills the crew at dawn. The crew hates it. The crew is better.","tags":["command"],"rank":1,"uses":0},{"hero":"h17","id":"snowcraft","name":"Snowcraft","desc":"Knows snow: which holds, which slides, which bites.","tags":["ice","travel"],"rank":1,"uses":0},{"hero":"h17","id":"pit_fighter","name":"Pit Fighter","desc":"Bets on themself in the pit. Collects.","tags":["rage"],"rank":1,"uses":0},{"hero":"h11","id":"warding_circle","name":"Warding Circle","desc":"Chalks a circle round the camp. Things stay outside it.","tags":["arcane"],"rank":2,"uses":0},{"hero":"h11","id":"card_sharp","name":"Card Sharp","desc":"The deck is always friendlier in their hands.","tags":[],"rank":1,"uses":0},{"hero":"h11","id":"bedside_manner","name":"Bedside Manner","desc":"Makes you feel better before the medicine does.","tags":["heal"],"rank":1,"uses":0},{"hero":"h11","id":"spellbook_copyist","name":"Spellbook Copyist","desc":"Copies spellbooks for wizards too busy to read their own.","tags":["arcane"],"rank":1,"uses":0},{"hero":"h11","id":"cantrips","name":"Cantrips","desc":"Small magic. Big crowds.","tags":["arcane","lore"],"rank":1,"uses":0},{"hero":"h11","id":"dice_luck","name":"Dice Luck","desc":"Rolls sixes when it matters, and only then.","tags":["trade","crit"],"rank":1,"uses":0},{"hero":"h1","id":"barterer","name":"Barterer","desc":"Will swap you anything for anything.","tags":["trade","travel"],"rank":1,"uses":0},{"hero":"h1","id":"grave_sense","name":"Grave Sense","desc":"Knows what the dead are worth, and to whom.","tags":["death"],"rank":1,"uses":0},{"hero":"h1","id":"price_memory","name":"Price Memory","desc":"Never forgets what a candle cost three winters ago.","tags":["trade"],"rank":1,"uses":0},{"hero":"h1","id":"rooftop_runner","name":"Rooftop Runner","desc":"Takes the high road. Literally.","tags":["stealth","travel"],"rank":1,"uses":0},{"hero":"h1","id":"glamour","name":"Glamour","desc":"Wears a better face to market.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h1","id":"scrying","name":"Scrying","desc":"Peers into a bowl of water and sees tomorrow, blurry.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h1","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h1","id":"pathfinding","name":"Pathfinding","desc":"Knows the back ways.","tags":["travel","nature"],"rank":1,"uses":0},{"hero":"h14","id":"pet_trick","name":"Good Pet","desc":"Their pet learned to fight. Sort of.","tags":["beast"],"rank":1,"uses":0},{"hero":"h14","id":"weather_eye","name":"Weather Eye","desc":"Smells rain two hours off.","tags":["storm"],"rank":2,"uses":0},{"hero":"h14","id":"speak_with_the_dead","name":"Speak with the Dead","desc":"Asks the corpse. The corpse is evasive.","tags":["death","lore"],"rank":1,"uses":0},{"hero":"h14","id":"icehouse","name":"Icehouse","desc":"Keeps the rations fresh for weeks.","tags":["ice"],"rank":1,"uses":0},{"hero":"h14","id":"dry_road","name":"Dry Road","desc":"Picks the road the rain isn't on. Every time.","tags":["storm"],"rank":2,"uses":0},{"hero":"h14","id":"busker","name":"Busker","desc":"Hat on the ground, song in the air.","tags":["music","travel"],"rank":1,"uses":0},{"hero":"h14","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h17","dmg":2712,"healed":235,"taken":432,"kills":11,"row":"front"},{"hero":"h11","dmg":774,"healed":338,"taken":208,"kills":3,"row":"back"},{"hero":"h1","dmg":1674,"healed":0,"taken":0,"kills":10,"row":"back"},{"hero":"h14","dmg":9879,"healed":0,"taken":1216,"kills":22,"row":"back"}],"ground":{"name":"The Ashveil Crypts","fights":10}},"trophies":[{"boss":"Gruk the Warchief's Heir","monster":"goblin_warchief","place":"Goblin Camp","day":34,"season":2,"fight":"f121"},{"boss":"Old Grizzlemaw's Widow","monster":"cave_bear","place":"The Wolf Den","day":41,"season":2,"fight":"f141"},{"boss":"The Mimic King's Ghost","monster":"mimic_king","place":"Cragtooth Warren","day":53,"season":2,"fight":"f184"},{"boss":"Vessimir the Unburied's Usurper","monster":"necromancer","place":"The Ashveil Crypts","day":71,"season":3,"fight":"f236"},{"boss":"The Mimic King's Second Coming","monster":"mimic_king","place":"Cragtooth Warren","day":82,"season":3,"fight":"f263"}]};